CREATE TYPE appointment_status AS ENUM ('BOOKED','CONFIRMED','CHECKED_IN','IN_PROGRESS','COMPLETED','CANCELLED','NO_SHOW');
CREATE TYPE queue_status AS ENUM ('WAITING','CALLED','IN_CONSULTATION','COMPLETED','SKIPPED','CANCELLED');
CREATE TABLE doctors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,specialty text NOT NULL,license_number text NOT NULL UNIQUE,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE doctor_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),doctor_id uuid NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,day_of_week integer NOT NULL,start_time time NOT NULL,end_time time NOT NULL,break_start time,break_end time,slot_duration_minutes integer NOT NULL DEFAULT 20,maximum_patients integer NOT NULL DEFAULT 12,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT doctor_schedules_day_check CHECK(day_of_week BETWEEN 0 AND 6),CONSTRAINT doctor_schedules_time_check CHECK(end_time>start_time),CONSTRAINT doctor_schedules_slot_check CHECK(slot_duration_minutes>0));
CREATE UNIQUE INDEX doctor_schedules_slot_uidx ON doctor_schedules(doctor_id,day_of_week,start_time);CREATE INDEX doctor_schedules_doctor_idx ON doctor_schedules(doctor_id);
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL UNIQUE,description text,duration_minutes integer NOT NULL DEFAULT 20,price numeric(14,2) NOT NULL,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT services_duration_check CHECK(duration_minutes>0),CONSTRAINT services_price_check CHECK(price>=0));
CREATE TABLE appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT,doctor_id uuid NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT,service_id uuid NOT NULL REFERENCES services(id) ON DELETE RESTRICT,appointment_date date NOT NULL,start_time time NOT NULL,end_time time NOT NULL,status appointment_status NOT NULL DEFAULT 'BOOKED',notes text,created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT appointments_time_check CHECK(end_time>start_time));
CREATE UNIQUE INDEX appointments_doctor_start_uidx ON appointments(doctor_id,appointment_date,start_time) WHERE status NOT IN ('CANCELLED','NO_SHOW');CREATE INDEX appointments_date_idx ON appointments(appointment_date);CREATE INDEX appointments_patient_idx ON appointments(patient_id);CREATE INDEX appointments_doctor_idx ON appointments(doctor_id);CREATE INDEX appointments_status_idx ON appointments(status);
CREATE TABLE queue_counters(queue_date date NOT NULL,prefix text NOT NULL,next_value integer NOT NULL DEFAULT 1,PRIMARY KEY(queue_date,prefix),CONSTRAINT queue_counters_positive_check CHECK(next_value>0));
CREATE TABLE queue_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid NOT NULL UNIQUE REFERENCES appointments(id) ON DELETE RESTRICT,patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT,doctor_id uuid NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT,queue_date date NOT NULL,queue_number text NOT NULL,status queue_status NOT NULL DEFAULT 'WAITING',checked_in_at timestamptz NOT NULL DEFAULT now(),called_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX queue_entries_number_uidx ON queue_entries(queue_date,queue_number);CREATE INDEX queue_entries_doctor_date_idx ON queue_entries(doctor_id,queue_date);CREATE INDEX queue_entries_status_idx ON queue_entries(status);
